# Disable Windows Search Indexing Service Write-Host "Disabling Windows Search Indexer (WSearch)..." -ForegroundColor Cyan # Stop the service Stop-Service -Name "WSearch" -Force -ErrorAction SilentlyContinue # Disable the service Set-Service -Name "WSearch" -StartupType Disabled -ErrorAction Stop Write-Host "Windows Search Indexer has been disabled." -ForegroundColor Green Write-Host "Note: File search in Start menu and Explorer will be slower." -ForegroundColor Yellow